image=json.loads((rel/'images.json').read_text())['investigator']['image']
spec={'hostNetwork':True,'dnsPolicy':'ClusterFirstWithHostNet','serviceAccountName':'ops-investigator','automountServiceAccountToken':False,'securityContext':{'runAsNonRoot':True,'runAsUser':65532,'runAsGroup':65532,'fsGroup':65532,'seccompProfile':{'type':'RuntimeDefault'}},'containers':[{'name':'investigator','image':image,'imagePullPolicy':'Never','command':['python','-c','import json; from investigator.worker import serve; serve(json.load(open("/etc/ops/runtime/investigator.json")))'],'env':[{'name':'PYTHONPATH','value':'/opt/ops-python'},{'name':'PYTHONDONTWRITEBYTECODE','value':'1'},{'name':'OPENBAO_ADDR','value':'https://ops-openbao.ops-current.svc.cluster.local:8200'},{'name':'OPENBAO_CA_FILE','value':'/etc/ops/runtime/bao-ca.pem'},{'name':'OPENBAO_PROJECTED_TOKEN_FILE','value':'/var/run/ops/openbao/token'}],'volumeMounts':[{'name':'runtime','mountPath':'/etc/ops/runtime','readOnly':True},{'name':'model','mountPath':'/run/model','readOnly':True},{'name':'projected','mountPath':'/var/run/ops/openbao','readOnly':True},{'name':'tmp','mountPath':'/tmp'}],'securityContext':{'allowPrivilegeEscalation':False,'readOnlyRootFilesystem':True,'capabilities':{'drop':['ALL']}},'resources':{'requests':{'cpu':'100m','memory':'256Mi'},'limits':{'cpu':'2','memory':'2Gi'}}}],'volumes':[{'name':'runtime','configMap':{'name':'ops-runtime'}},{'name':'model','secret':{'secretName':'ops-model','defaultMode':0o440}},{'name':'projected','projected':{'defaultMode':0o444,'sources':[{'serviceAccountToken':{'path':'token','audience':'openbao','expirationSeconds':600}}]}},{'name':'tmp','emptyDir':{}}]}
apply({'apiVersion':'apps/v1','kind':'Deployment','metadata':{'name':'ops-investigator','namespace':ns},'spec':{'replicas':1,'strategy':{'type':'Recreate'},'selector':{'matchLabels':{'app':'ops-investigator'}},'template':{'metadata':{'labels':{'app':'ops-investigator'},'annotations':{'ops.platform.io/git-commit':rel.name}},'spec':spec}}})
